// ---- _shared/auth.ts ---------------------------------
// Shared caller authentication for edge functions (Phase 0, SEC-01).
//
// Rule (docs/cpo/09-security-baseline.md §2): a function derives tenant access
// from a VERIFIED credential, never from a header or body. For calls made by a
// signed-in app user, the safest pattern is to act AS that user: queries run
// through a client carrying the user's JWT, so Postgres RLS enforces tenant
// isolation even if function code has a bug. Use the service role only after
// authentication, and only for work RLS can't express.


class AuthError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type AuthedUser = {
  userId: string;
  email: string | null;
  /** Client that runs every query as the caller — RLS applies. */
  db: SupabaseClient;
};

const AUTH_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireEnv(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new AuthError(500, `Server misconfigured: ${name} is not set`);
  return v;
}

/** Verify the bearer token belongs to a real signed-in user (not the anon key). */
async function authenticateUser(req: Request): Promise<AuthedUser> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');

  const db = createClient(requireEnv('SUPABASE_URL'), requireEnv('SUPABASE_ANON_KEY'), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // getUser validates signature + expiry with Auth; the anon key has no user and fails here.
  const { data, error } = await db.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');

  return { userId: data.user.id, email: data.user.email ?? null, db };
}

/** Confirm the caller is an active member of the tenant (checked by the database as the caller). */
async function requireTenantMember(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (typeof tenantId !== 'string' || !AUTH_UUID_RE.test(tenantId)) throw new AuthError(400, 'tenant_id must be a UUID');
  const { data, error } = await user.db.rpc('user_has_tenant_access', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant membership check failed', error.message);
    throw new AuthError(500, 'Could not verify tenant access');
  }
  if (data !== true) throw new AuthError(403, 'No access to this tenant');
  return tenantId.toLowerCase();
}

/** Tenant named by the caller (membership verified), or the caller's own active membership. */
async function resolveTenant(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (tenantId !== undefined && tenantId !== null && tenantId !== '') return requireTenantMember(user, tenantId);
  const { data, error } = await user.db.from('tenant_users').select('tenant_id')
    .eq('user_id', user.userId).eq('status', 'active').order('created_at').limit(1);
  if (error) throw new AuthError(500, 'Could not resolve your workspace');
  const t = data?.[0]?.tenant_id as string | undefined;
  if (!t) throw new AuthError(403, 'You are not a member of any workspace');
  return t;
}

/** Throws 403 unless the caller holds `permission` in the tenant (tenant admins hold all). */
async function requirePermission(user: AuthedUser, tenantId: string, permission: string, label?: string): Promise<void> {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: permission });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, `You need the "${label ?? permission}" permission for this`);
}

// ---- _shared/ingest-auth.ts ------------------------------------------------------------------
// Authentication for PUBLIC ingest endpoints (Phase 0, SEC-02).
//
// Two credential types — tenant/environment always come from the credential, never the request:
//   • Secret API key (server-to-server): `x-api-key: mk_…` or `Authorization: Bearer mk_…`.
//     Verified by public.verify_api_key() (bcrypt). Must carry the required scope.
//   • Site key (browser SDKs): body `site_id` + `write_key` (public by design, like a
//     Segment write key). Verified by public.resolve_ingest_site(): key, site status and
//     the browser Origin against the site's domain / allowed_origins.
//
// Because a site key is public, it can be copied and replayed from a script. Defences:
// per-site + per-IP rate limits here (per isolate — a backstop), frequency caps at send
// time (Wave 1 guardrails), and identity verification for identified users (SEC-13).


type IngestContext = {
  tenantId: string;
  environment: string;
  via: 'api_key' | 'site_key';
  siteId?: string;
  siteUuid?: string;
};

/** Read the secret API key if one was sent. JWTs (anon/user tokens) are ignored here. */
function readApiKey(req: Request): string | null {
  const header = req.headers.get('x-api-key')?.trim();
  if (header) return header;
  const auth = req.headers.get('authorization') ?? '';
  const bearer = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
  // Supabase JWTs have three dot-separated parts; Marbee API keys don't.
  if (bearer && bearer.split('.').length !== 3) return bearer;
  return null;
}

async function authenticateApiKey(db: SupabaseClient, rawKey: string, scope: string): Promise<IngestContext> {
  const { data, error } = await db.rpc('verify_api_key', { p_raw_key: rawKey });
  if (error) {
    console.error('verify_api_key failed', error.message);
    throw new AuthError(500, 'Could not verify API key');
  }
  const row = Array.isArray(data) ? data[0] : null;
  if (!row) throw new AuthError(401, 'Invalid or revoked API key');
  const scopes: string[] = row.scopes ?? [];
  if (!scopes.includes(scope) && !scopes.includes('*')) throw new AuthError(403, `API key is missing the ${scope} scope`);
  return { tenantId: row.tenant_id, environment: row.environment ?? 'production', via: 'api_key' };
}

async function authenticateSiteKey(
  db: SupabaseClient,
  siteId: unknown,
  writeKey: unknown,
  origin: string | null,
): Promise<IngestContext> {
  if (typeof siteId !== 'string' || typeof writeKey !== 'string') {
    throw new AuthError(401, 'site_id and write_key are required');
  }
  const { data, error } = await db.rpc('resolve_ingest_site', {
    p_site_id: siteId, p_write_key: writeKey, p_origin: origin,
  });
  if (error) {
    console.error('resolve_ingest_site failed', error.message);
    throw new AuthError(500, 'Could not verify site key');
  }
  const r = data as { ok: boolean; reason?: string; tenant_id?: string; environment?: string; site_id?: string; site_uuid?: string };
  if (!r?.ok) {
    const status = r?.reason === 'invalid_key' ? 401 : 403;
    const message = r?.reason === 'origin_not_allowed'
      ? 'This website is not allowed to use this site key'
      : r?.reason?.startsWith('site_') ? 'Site is not active' : 'Invalid site key';
    throw new AuthError(status, message);
  }
  return { tenantId: r.tenant_id!, environment: r.environment ?? 'production', via: 'site_key', siteId: r.site_id, siteUuid: r.site_uuid };
}

/** API key if present, otherwise site key from the parsed body. */
async function authenticateIngest(
  req: Request,
  db: SupabaseClient,
  body: Record<string, unknown> | null,
  scope: string,
): Promise<IngestContext> {
  const apiKey = readApiKey(req);
  if (apiKey) return authenticateApiKey(db, apiKey, scope);
  return authenticateSiteKey(db, body?.site_id, body?.write_key, req.headers.get('origin'));
}

// --------------------------------------------------------------------------------------
// Rate limit — fixed window per isolate. A backstop against floods, not a billing meter.
// --------------------------------------------------------------------------------------
const windows = new Map<string, { start: number; count: number }>();

function rateLimited(key: string, max: number, windowMs = 60_000): boolean {
  const now = Date.now();
  const w = windows.get(key);
  if (!w || now - w.start >= windowMs) {
    windows.set(key, { start: now, count: 1 });
    if (windows.size > 10_000) windows.clear(); // bound memory
    return false;
  }
  w.count += 1;
  return w.count > max;
}

function clientIp(req: Request): string {
  return req.headers.get('cf-connecting-ip')
    ?? req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    ?? 'unknown';
}

/** Reject oversized bodies before parsing (Content-Length when present). */
function tooLarge(req: Request, maxBytes: number): boolean {
  const len = Number(req.headers.get('content-length') ?? 0);
  return Number.isFinite(len) && len > maxBytes;
}

// ---- _shared/llm.ts ----------------------------------
// Provider-agnostic LLM adapter shared by chatbot-runtime and ai-gateway.
// Mirrors the endpoints used by apps/web/src/lib/ai-crm-context.ts, but runs
// server-side only — the API key never leaves this Edge Function.

type LlmProvider = 'openai' | 'gemini' | 'claude' | 'grok' | 'deepseek' | 'groq' | 'openrouter' | 'jev' | 'custom_llm';

type LlmCallInput = {
  provider: LlmProvider;
  model: string;
  apiKey: string;
  baseUrl?: string;
  systemPrompt: string;
  userMessage: string;
  temperature: number;
  maxTokens: number;
  timeoutMs: number;
};

type LlmCallResult = {
  text: string;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  latencyMs: number;
};

const OPENAI_COMPATIBLE_ENDPOINTS: Partial<Record<LlmProvider, string>> = {
  openai: 'https://api.openai.com/v1/chat/completions',
  deepseek: 'https://api.deepseek.com/v1/chat/completions',
  grok: 'https://api.x.ai/v1/chat/completions',
  groq: 'https://api.groq.com/openai/v1/chat/completions',
  openrouter: 'https://openrouter.ai/api/v1/chat/completions',
  custom_llm: 'https://api.openai.com/v1/chat/completions',
};

async function callOpenAiCompatible(input: LlmCallInput): Promise<LlmCallResult> {
  const endpoint = input.baseUrl || OPENAI_COMPATIBLE_ENDPOINTS[input.provider] || OPENAI_COMPATIBLE_ENDPOINTS.openai!;
  const start = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), input.timeoutMs);

  try {
    const headers: Record<string, string> = {
      Authorization: `Bearer ${input.apiKey}`,
      'Content-Type': 'application/json',
    };
    if (input.provider === 'openrouter') {
      headers['HTTP-Referer'] = 'https://app.marbee.io';
      headers['X-OpenRouter-Title'] = 'Marbee';
    }

    const body: Record<string, unknown> = {
      model: input.model,
      temperature: input.temperature,
      max_tokens: input.maxTokens,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: input.systemPrompt },
        { role: 'user', content: input.userMessage },
      ],
    };
    if (input.provider === 'openrouter' && !input.model.startsWith('openrouter/')) {
      body.models = [
        input.model,
        '~anthropic/claude-sonnet-latest',
        '~openai/gpt-sol-latest',
        'google/gemini-2.0-flash-001',
      ];
    }

    const res = await fetch(endpoint, {
      method: 'POST',
      signal: controller.signal,
      headers,
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const errText = await res.text();
      throw new Error(`${input.provider} error (${res.status}): ${errText.slice(0, 300)}`);
    }

    const json = await res.json();
    const text = json.choices?.[0]?.message?.content ?? '';
    const usage = json.usage ?? {};
    return {
      text,
      promptTokens: usage.prompt_tokens ?? 0,
      completionTokens: usage.completion_tokens ?? 0,
      totalTokens: usage.total_tokens ?? 0,
      latencyMs: Date.now() - start,
    };
  } finally {
    clearTimeout(timer);
  }
}

async function callAnthropic(input: LlmCallInput): Promise<LlmCallResult> {
  const start = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), input.timeoutMs);

  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'x-api-key': input.apiKey,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: input.model,
        max_tokens: input.maxTokens,
        temperature: input.temperature,
        system: `${input.systemPrompt}\n\nRespond with ONLY valid JSON, no markdown fences.`,
        messages: [{ role: 'user', content: input.userMessage }],
      }),
    });

    if (!res.ok) {
      const errText = await res.text();
      throw new Error(`claude error (${res.status}): ${errText.slice(0, 300)}`);
    }

    const json = await res.json();
    const text = (json.content ?? []).map((b: { text?: string }) => b.text ?? '').join('');
    const usage = json.usage ?? {};
    const inputTok = usage.input_tokens ?? 0;
    const outputTok = usage.output_tokens ?? 0;
    return {
      text,
      promptTokens: inputTok,
      completionTokens: outputTok,
      totalTokens: inputTok + outputTok,
      latencyMs: Date.now() - start,
    };
  } finally {
    clearTimeout(timer);
  }
}

async function callGemini(input: LlmCallInput): Promise<LlmCallResult> {
  const start = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), input.timeoutMs);
  const model = input.model || 'gemini-2.0-flash';
  const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${input.apiKey}`;

  try {
    const res = await fetch(endpoint, {
      method: 'POST',
      signal: controller.signal,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        systemInstruction: { parts: [{ text: input.systemPrompt }] },
        contents: [{ role: 'user', parts: [{ text: input.userMessage }] }],
        generationConfig: {
          temperature: input.temperature,
          maxOutputTokens: input.maxTokens,
          responseMimeType: 'application/json',
        },
      }),
    });

    if (!res.ok) {
      const errText = await res.text();
      throw new Error(`gemini error (${res.status}): ${errText.slice(0, 300)}`);
    }

    const json = await res.json();
    const text = json.candidates?.[0]?.content?.parts?.map((p: { text?: string }) => p.text ?? '').join('') ?? '';
    const usage = json.usageMetadata ?? {};
    return {
      text,
      promptTokens: usage.promptTokenCount ?? 0,
      completionTokens: usage.candidatesTokenCount ?? 0,
      totalTokens: usage.totalTokenCount ?? 0,
      latencyMs: Date.now() - start,
    };
  } finally {
    clearTimeout(timer);
  }
}

/** Call the configured LLM provider. Retries `retryCount` times on failure/timeout. */
async function callLlm(input: LlmCallInput, retryCount = 0): Promise<LlmCallResult> {
  let lastError: unknown;
  for (let attempt = 0; attempt <= retryCount; attempt++) {
    try {
      if (input.provider === 'claude') return await callAnthropic(input);
      if (input.provider === 'gemini') return await callGemini(input);
      return await callOpenAiCompatible(input);
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError instanceof Error ? lastError : new Error('LLM call failed');
}

/** Resolve the server-side secret for a provider. Never sourced from the browser. */
function resolveProviderApiKey(provider: string, dbFallbackKey?: string | null): string | null {
  const envKeyByProvider: Record<string, string> = {
    openai: 'OPENAI_API_KEY',
    claude: 'ANTHROPIC_API_KEY',
    gemini: 'GEMINI_API_KEY',
    grok: 'XAI_API_KEY',
    deepseek: 'DEEPSEEK_API_KEY',
    groq: 'GROQ_API_KEY',
    openrouter: 'OPENROUTER_API_KEY',
    jev: 'JEV_API_KEY',
    custom_llm: 'CUSTOM_LLM_API_KEY',
  };
  const envVarName = envKeyByProvider[provider];
  if (envVarName) {
    const fromEnv = Deno.env.get(envVarName)?.trim();
    if (fromEnv) return fromEnv;
  }
  const fromDb = dbFallbackKey?.trim();
  return fromDb || null;
}

// ---- _shared/secret-box.ts -------------------------------------------------------------------
// Server-side secret sealing (Phase 0 · SEC-05/SEC-07).
//
// Seals tenant secrets (AI provider keys, global-variable secrets) with AES-256-GCM
// using ONE server-only master key: the edge-function secret MARBEE_SECRETS_KEY
// (32 random bytes, base64). The database only ever stores the sealed envelope:
//
//     mbs1.<base64 12-byte IV>.<base64 ciphertext+tag>
//
// The browser never sees the master key or the plaintext. Values written before this
// existed are plaintext ("legacy"); openSecret() still returns them so nothing breaks,
// and callers re-seal them on next use.
//
// Generate a key:  node -e "console.log(require('crypto').randomBytes(32).toString('base64'))"
// Set it:          Supabase Dashboard → Edge Functions → Secrets → MARBEE_SECRETS_KEY

const PREFIX = 'mbs1';
const enc = new TextEncoder();
const dec = new TextDecoder();

let cachedKey: CryptoKey | null = null;
let cachedFrom: string | null = null;

function b64(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i += 1) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function unb64(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

function readMasterKey(): string {
  // deno-lint-ignore no-explicit-any
  const env = (globalThis as any).Deno?.env;
  const v = env?.get('MARBEE_SECRETS_KEY')?.trim();
  if (!v) throw new Error('Server misconfigured: MARBEE_SECRETS_KEY is not set');
  return v;
}

async function masterKey(): Promise<CryptoKey> {
  const material = readMasterKey();
  if (cachedKey && cachedFrom === material) return cachedKey;
  const raw = unb64(material);
  if (raw.length !== 32) throw new Error('MARBEE_SECRETS_KEY must be 32 bytes (base64)');
  cachedKey = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  cachedFrom = material;
  return cachedKey;
}

function isSealed(value: string | null | undefined): boolean {
  return typeof value === 'string' && value.startsWith(`${PREFIX}.`);
}

/** Encrypt a secret for storage. */
async function sealSecret(plaintext: string): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await masterKey(), enc.encode(plaintext)));
  return `${PREFIX}.${b64(iv)}.${b64(ct)}`;
}

/** Decrypt a stored secret. Legacy plaintext is returned as-is; empty → null. Tampered → throws. */
async function openSecret(stored: string | null | undefined): Promise<string | null> {
  if (stored === null || stored === undefined) return null;
  const v = stored.trim();
  if (!v) return null;
  if (!isSealed(v)) return v; // legacy plaintext — caller should re-seal
  const [, ivB64, ctB64] = v.split('.');
  if (!ivB64 || !ctB64) throw new Error('Malformed sealed secret');
  const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(ivB64) }, await masterKey(), unb64(ctB64));
  return dec.decode(pt);
}

/** "…abcd" for display. Never reveals more than the last 4 characters. */
function last4(plaintext: string): string {
  const t = plaintext.trim();
  return t.length <= 4 ? '' : t.slice(-4);
}

// ---- ai-gateway/index.ts ---------------------------------------------------------------------
// ai-gateway — the ONLY way the Marbee app talks to an LLM (D-018, Phase 0 · SEC-06/SEC-07).
//
// The browser sends prompts; this function picks the key, calls the provider, meters
// usage, and returns text. Provider keys never reach the browser:
//   • tenant keys live sealed in ai_engine_providers.api_key_encrypted (MARBEE_SECRETS_KEY)
//     and the column isn't even readable by app users (sql/89);
//   • otherwise Marbee's platform key from function secrets is used, and the call is
//     debited from the tenant's AI credits (D-015) when a wallet exists.
//
// Ops (POST JSON, signed-in user JWT required; deploy with JWT verification ON):
//   complete  { tenant_id, environment?, provider?, model?, system_prompt, user_message,
//               temperature?, max_tokens?, candidate_key? }  → { text, provider, model, source, latency_ms, tokens }
//   save_key  { tenant_id, environment?, provider, model_name, api_key }      (settings.manage)
//   clear_key { tenant_id, environment?, provider, model_name }               (settings.manage)


const PROVIDERS: readonly LlmProvider[] = ['openai', 'gemini', 'claude', 'grok', 'deepseek', 'groq', 'openrouter', 'jev', 'custom_llm'];
const DEFAULT_MODEL: Record<string, string> = {
  openai: 'gpt-4o-mini', gemini: 'gemini-2.0-flash', claude: 'claude-3-5-haiku-latest', grok: 'grok-2-latest',
  deepseek: 'deepseek-chat', groq: 'llama-3.1-8b-instant', openrouter: 'openai/gpt-4o-mini', jev: 'jev-latest', custom_llm: 'gpt-4o-mini',
};
const ENVIRONMENTS = ['production', 'staging', 'development'];
const MAX_PROMPT_CHARS = 24_000;

type Json = Record<string, unknown>;

function str(v: unknown, max: number): string | null {
  return typeof v === 'string' && v.trim() ? v.slice(0, max) : null;
}
function env(p: Json): string {
  const e = typeof p.environment === 'string' ? p.environment : 'production';
  if (!ENVIRONMENTS.includes(e)) throw new AuthError(400, 'Invalid environment');
  return e;
}
function provider(p: Json, required: boolean): LlmProvider | null {
  const v = p.provider;
  if (v === undefined || v === null || v === '') {
    if (required) throw new AuthError(400, 'provider is required');
    return null;
  }
  if (typeof v !== 'string' || !(PROVIDERS as readonly string[]).includes(v)) throw new AuthError(400, 'Unknown provider');
  return v as LlmProvider;
}
async function requireSettingsManager(user: AuthedUser, tenantId: string) {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: 'settings.manage' });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, 'You need the "Manage settings" permission to change AI keys');
}


// --------------------------------------------------------------------------------------
async function complete(user: AuthedUser, p: Json) {
  const tenantId = await resolveTenant(user, p.tenant_id);
  const environment = env(p);
  const wantProvider = provider(p, false);
  const systemPrompt = str(p.system_prompt, MAX_PROMPT_CHARS) ?? 'You are a helpful assistant for the Marbee platform.';
  const userMessage = str(p.user_message, MAX_PROMPT_CHARS);
  if (!userMessage) throw new AuthError(400, 'user_message is required');
  const temperature = Math.min(Math.max(Number(p.temperature ?? 0.7) || 0.7, 0), 1.5);
  const maxTokens = Math.min(Math.max(Number(p.max_tokens ?? 1024) || 1024, 16), 4096);
  if (rateLimited(`ai:${user.userId}`, 40)) throw new AuthError(429, 'Too many AI requests — wait a moment');

  const svc = getServiceClient();
  let apiKey: string | null = null;
  let source: 'candidate' | 'tenant_key' | 'platform' = 'platform';
  let chosenProvider: LlmProvider = wantProvider ?? 'openai';
  let model = str(p.model, 120) ?? '';
  let baseUrl: string | undefined;

  // 1. A key the admin is testing before saving it (never stored here).
  const candidate = str(p.candidate_key, 512);
  if (candidate && !candidate.startsWith('••')) {
    await requireSettingsManager(user, tenantId);
    apiKey = candidate.trim();
    source = 'candidate';
  }

  // 2. The tenant's own configured key.
  if (!apiKey) {
    let q = svc.from('ai_engine_providers')
      .select('id, provider, model_name, api_key_encrypted, base_url, is_default')
      .eq('tenant_id', tenantId).eq('environment', environment).not('api_key_encrypted', 'is', null);
    if (wantProvider) q = q.eq('provider', wantProvider);
    const { data: rows } = await q.order('is_default', { ascending: false }).limit(20);
    const row = (rows ?? []).find((r) => !model || r.model_name === model) ?? (rows ?? [])[0];
    if (row?.api_key_encrypted) {
      try {
        apiKey = await openSecret(row.api_key_encrypted as string);
      } catch (e) {
        console.error('ai-gateway: could not open tenant key', e instanceof Error ? e.message : e);
        throw new AuthError(500, 'Stored AI key could not be decrypted — re-enter it in Settings → AI Engine');
      }
      if (apiKey) {
        source = 'tenant_key';
        chosenProvider = row.provider as LlmProvider;
        model = model || (row.model_name as string);
        baseUrl = (row.base_url as string) || undefined;
        // Re-seal legacy plaintext keys on first use.
        if (!isSealed(row.api_key_encrypted as string)) {
          await svc.from('ai_engine_providers').update({
            api_key_encrypted: await sealSecret(apiKey), api_key_last4: last4(apiKey),
          }).eq('id', row.id);
        }
      }
    }
  }

  // 3. Marbee's platform key (function secrets), metered against AI credits.
  if (!apiKey) {
    apiKey = resolveProviderApiKey(chosenProvider, null);
    source = 'platform';
    if (!apiKey) throw new AuthError(503, 'No AI key is configured for this workspace');
  }
  model = model || DEFAULT_MODEL[chosenProvider] || 'gpt-4o-mini';

  let metered: 'debited' | 'no_wallet' | 'not_metered' = 'not_metered';
  if (source === 'platform') {
    const { data: rate } = await svc.from('credit_rate_card').select('credits_per_unit').eq('service', 'ai_generation').maybeSingle();
    const credits = Number(rate?.credits_per_unit ?? 0);
    if (credits > 0) {
      const { data: debit, error: debitErr } = await svc.rpc('credit_debit', {
        p_tenant_id: tenantId, p_service: 'ai_generation', p_credits: credits, p_quantity: 1,
        p_transactional: false, p_idempotency_key: `ai:${crypto.randomUUID()}`, p_metadata: { user_id: user.userId, model },
      });
      if (debitErr) {
        console.error('ai-gateway: credit_debit failed', debitErr.message);
      } else if ((debit as Json)?.ok === false && (debit as Json)?.reason === 'insufficient_credits') {
        throw new AuthError(402, 'Not enough AI credits — top up in your Marbee plan');
      } else {
        metered = (debit as Json)?.ok ? 'debited' : 'no_wallet'; // no wallet yet = pre-billing (dev / not onboarded)
      }
    }
  }

  try {
    const r = await callLlm({ provider: chosenProvider, model, apiKey, baseUrl, systemPrompt, userMessage, temperature, maxTokens, timeoutMs: 45_000 }, 1);
    return { text: r.text, provider: chosenProvider, model, source, metered, latency_ms: r.latencyMs, tokens: r.totalTokens };
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'LLM call failed';
    console.error('ai-gateway: provider call failed', chosenProvider, msg.slice(0, 300));
    // Surface auth problems clearly without echoing provider internals.
    if (/401|403|invalid.*key|unauthori/i.test(msg)) throw new AuthError(502, `The ${chosenProvider} key was rejected by the provider`);
    throw new AuthError(502, `The ${chosenProvider} request failed — try again`);
  }
}

async function saveKey(user: AuthedUser, p: Json) {
  const tenantId = await requireTenantMember(user, p.tenant_id);
  await requireSettingsManager(user, tenantId);
  const environment = env(p);
  const prov = provider(p, true)!;
  const modelName = str(p.model_name, 120);
  const apiKey = str(p.api_key, 512)?.trim();
  if (!modelName) throw new AuthError(400, 'model_name is required');
  if (!apiKey || apiKey.length < 8 || apiKey.startsWith('••')) throw new AuthError(400, 'A real API key is required');

  const svc = getServiceClient();
  const sealed = await sealSecret(apiKey);
  const { data, error } = await svc.from('ai_engine_providers')
    .update({ api_key_encrypted: sealed, api_key_last4: last4(apiKey), status: 'unverified', updated_at: new Date().toISOString() })
    .eq('tenant_id', tenantId).eq('environment', environment).eq('provider', prov).eq('model_name', modelName)
    .select('id');
  if (error) {
    console.error('ai-gateway save_key failed', error.message);
    throw new AuthError(500, 'Could not save the key');
  }
  if (!data?.length) throw new AuthError(404, 'Save the model first, then add its key');
  const { error: auditErr } = await svc.from('audit_logs').insert({
    tenant_id: tenantId, environment, user_id: user.userId, action: 'update', resource_type: 'ai_engine_key',
    resource_id: data[0].id, metadata: { provider: prov, model_name: modelName, key_last4: last4(apiKey) },
  });
  if (auditErr) console.error('ai-gateway: audit insert failed', auditErr.message);
  return { saved: true, last4: last4(apiKey) };
}

async function clearKey(user: AuthedUser, p: Json) {
  const tenantId = await requireTenantMember(user, p.tenant_id);
  await requireSettingsManager(user, tenantId);
  const environment = env(p);
  const prov = provider(p, true)!;
  const modelName = str(p.model_name, 120);
  if (!modelName) throw new AuthError(400, 'model_name is required');
  const { error } = await getServiceClient().from('ai_engine_providers')
    .update({ api_key_encrypted: null, api_key_last4: null, status: 'unconfigured', updated_at: new Date().toISOString() })
    .eq('tenant_id', tenantId).eq('environment', environment).eq('provider', prov).eq('model_name', modelName);
  if (error) throw new AuthError(500, 'Could not clear the key');
  const { error: auditErr } = await getServiceClient().from('audit_logs').insert({
    tenant_id: tenantId, environment, user_id: user.userId, action: 'delete', resource_type: 'ai_engine_key',
    metadata: { provider: prov, model_name: modelName },
  });
  if (auditErr) console.error('ai-gateway: audit insert failed', auditErr.message);
  return { cleared: true };
}

/** Seal every legacy plaintext key in the caller's workspace now (instead of on first use). */
async function resealKeys(user: AuthedUser, p: Json) {
  const tenantId = await resolveTenant(user, p.tenant_id);
  await requireSettingsManager(user, tenantId);
  const svc = getServiceClient();
  const { data: rows, error } = await svc.from('ai_engine_providers')
    .select('id, api_key_encrypted').eq('tenant_id', tenantId).not('api_key_encrypted', 'is', null);
  if (error) throw new AuthError(500, 'Could not read provider keys');
  let sealed = 0;
  let alreadySealed = 0;
  for (const r of rows ?? []) {
    const stored = String(r.api_key_encrypted ?? '').trim();
    if (!stored) continue;
    if (isSealed(stored)) { alreadySealed += 1; continue; }
    const { error: upErr } = await svc.from('ai_engine_providers')
      .update({ api_key_encrypted: await sealSecret(stored), api_key_last4: last4(stored) }).eq('id', r.id);
    if (upErr) throw new AuthError(500, 'Could not seal a key');
    sealed += 1;
  }
  const { error: auditErr } = await svc.from('audit_logs').insert({
    tenant_id: tenantId, environment: 'production', user_id: user.userId, action: 'update', resource_type: 'ai_engine_key',
    metadata: { op: 'reseal_keys', sealed, already_sealed: alreadySealed },
  });
  if (auditErr) console.error('ai-gateway: audit insert failed', auditErr.message);
  return { sealed, already_sealed: alreadySealed };
}

const OPS: Record<string, (u: AuthedUser, p: Json) => Promise<unknown>> = {
  complete, save_key: saveKey, clear_key: clearKey, reseal_keys: resealKeys,
};

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders() });
  if (req.method !== 'POST') return errorResponse('Method not allowed', 405);
  try {
    const user = await authenticateUser(req);
    const body = (await req.json().catch(() => null)) as Json | null;
    if (!body || typeof body !== 'object' || Array.isArray(body)) return errorResponse('JSON body required', 400);
    const op = typeof body.op === 'string' ? body.op : '';
    const handler = Object.prototype.hasOwnProperty.call(OPS, op) ? OPS[op] : undefined;
    if (!handler) return errorResponse('Unknown operation', 400);
    return jsonResponse({ data: await handler(user, body) });
  } catch (e) {
    if (e instanceof AuthError) return errorResponse(e.message, e.status);
    console.error('ai-gateway unhandled', e instanceof Error ? e.message : e);
    return errorResponse('Internal error', 500);
  }
});
